export function getLocalizedArticles(locale: SiteLocale): Article[] {
  if (locale === "en") return articles;
  return articles.map(article => ({ ...article, ...arabicArticles[article.slug] }));
}

export function getLocalizedArticle(slug: string, locale: SiteLocale): Article | undefined {
  return getLocalizedArticles(locale).find(article => article.slug === slug);
}
